parameters.jsCode:
// ============================
// 解析老板引用回复的意图（v4：上下文来自 /api/n8n/lead?alert=<消息id>，不再查 Google Sheet）
// 「1 / 确认 / 已收款 / ok」→ 收款确认 → 自动建单（wa-order confirm）
// [QR] 标记 → 转达 + 发收款码；[bot] 标记 → 转达后释放人工接管；其余 → Gemini 润色后转达
// ============================

const rawBossText = $('Router').first().json.text || '';
const lookup = $('Boss Lookup').first().json || {};
const customerPhone = String(lookup.phone || '').replace(/[^0-9]/g, '');
const customerMsg = String(lookup.customerMsg || '');

const isConfirm = /^(1|确认|已收款|收到钱|ok|okay)$/i.test(rawBossText.trim());
const needSendQR = /\[QR\]|\[发QR\]|\[SEND_QR\]/i.test(rawBossText);
const releaseBot = /\[bot\]|\[机器\]|\[恢复\]/i.test(rawBossText);

let cleanBossText = rawBossText
  .replace(/\[QR\]/gi, '').replace(/\[发QR\]/gi, '').replace(/\[SEND_QR\]/gi, '')
  .replace(/\[bot\]/gi, '').replace(/\[机器\]/g, '').replace(/\[恢复\]/g, '')
  .trim();
if (!cleanBossText) cleanBossText = needSendQR ? '请客户用以下二维码扫码付款' : '好的，碗妈这边继续帮你跟进';

return [{ json: { customerPhone, customerMsg, bossText: cleanBossText, needSendQR, isConfirm, releaseBot } }];

// ============================
// 建单结果 → 老板通知 + 客户确认话术
// ============================

const r = $('WA Confirm Order').first()?.json || {};
const phone = $('Parse Boss Intent').first().json.customerPhone;

let bossText = '';
let custText = '';

if (r.ok && r.alreadyConfirmed) {
  bossText = '✅ 这单之前已经确认建过了，没有重复建单。';
} else if (r.ok) {
  const n = Array.isArray(r.created) ? r.created.length : 0;
  bossText = `✅ 收款确认！已自动建 ${n} 张单进系统（dashboard／备餐单／库存都会自动跟上）。\n${r.summaryText || ''}`;
  custText = `付款核对好啦 ✅ 订单确认！\n${r.summaryText || ''}\n碗妈会准时为您出餐，谢谢支持 ❤️`;
} else {
  const errMsg = (r.error && typeof r.error === 'object') ? (r.error.message || JSON.stringify(r.error)) : (r.error || '接口无响应');
  bossText = `⚠️ 自动建单失败：${errMsg}\n请去 dashboard 手动录单，客户已付款别漏。`;
}

return [{ json: { phone, bossText, custText, ok: !!r.ok } }];

const output = $input.first().json;

// 从 parts 里只取没有 thought:true 的那个
const parts = output.content?.parts || [];
const finalPart = parts.find(p => !p.thought);

return [{
  json: {
    text: finalPart?.text || parts[parts.length - 1]?.text || ''
  }
}];

// ============================
// 后处理 v2：统一求救标记 —— 只有 [求救老板]，并用 /\[求救[^\]]*\]/ 兜底，
// 任何带「求救」的方括号标记都会被识别 + 剥除（修复 v1 双标记漏网 bug）。
// ============================

const aiReply = $input.first().json.output || '';
const phone = $('Router').first().json.phone;
const customerMsg = $('Message Gate').first().json.text || $('Router').first().json.text || '';

const needEscalate = /\[求救[^\]]*\]/.test(aiReply);
const needQR = /\[SEND_QR\]/i.test(aiReply);
const dishMatch = aiReply.match(/\[SEND_DISH:([a-z0-9_\-]+)\]/i);

let cleanReply = aiReply
  .replace(/\[求救[^\]]*\]/g, '')
  .replace(/\[SEND_QR\]/gi, '')
  .replace(/\[SEND_DISH:[a-z0-9_\-]+\]/gi, '')
  .trim();

let action = 'normal';
if (needEscalate) action = 'escalate';
else if (needQR) action = 'send_qr';
else if (dishMatch) action = 'send_dish';

if (!cleanReply) {
  action = 'escalate';
  cleanReply = '不好意思亲！这个碗妈得跟老板确认一下，稍等哦 ❤️';
}

return [{
  json: {
    phone,
    customerMsg,
    reply: cleanReply,
    action,
    dishId: dishMatch ? dishMatch[1].toLowerCase() : ''
  }
}];

// ============================
// 首触话术（确定性，不经 LLM）。v2 的病根是「AI 要客户打字说清 6 样信息」，
// 这里反过来：**第一条就把客户做决定需要的东西一次给全**，并给一个能点的入口。
//
// 三套剧本：
//   catering  团餐 —— 报价规则/餐具/准点/收据全给，只问 3 样
//   returning 老客 —— 「还是老样子吗」+ 预填好的复购链接
//   new       新客 —— 菜单 + RM5 + 一键下单链接
// 全部中英双语，跟着 Router 判出来的 lang 走。
// ============================

const r = $('Router').first().json;
const lead = $('Lead Touch').first().json?.lead || {};
const menu = $('Get Menu Greet').first()?.json || {};
const cust = $('Get Customer Greet').first()?.json || {};

const zh = r.lang !== 'en';
const token = lead.clickToken || '';
const tag = token ? ('&lead=' + token) : '';

// 菜单读不到 → 绝不凭记忆编菜（v2 之前出过三次「报旧菜单骗客户」）
const menuOk = typeof menu.today_menu_short === 'string' && menu.today_menu_short.length > 0;
const menuBlock = menuOk ? (zh ? menu.today_menu_short : (menu.today_menu_short_en || menu.today_menu_short)) : '';
const label = zh ? (menu.delivery_label || '') : (menu.delivery_label_en || menu.delivery_label || '');
const baseUrl = (zh ? (menu.order_url || 'https://www.incredibowl.my/o?ref=wa') : (menu.order_url_en || 'https://www.incredibowl.my/en/o?ref=wa')) + tag;

if (!menuOk) {
  return [{ json: {
    phone: r.phone,
    reply: zh
      ? '亲爱的，碗妈这边系统卡了一下，稍等碗妈马上回你 ❤️'
      : 'Hi dear! Give BowlMama a moment, replying to you right away ❤️',
    kind: 'menu_down',
    escalate: true,
  }}];
}

// 配送情境（周末 / 已过截单 / 还没截单）中英同源，都来自 /api/n8n/menu。
// 绝不在这里硬编码「6 点截单」—— 周末说这句会让客户以为今天还能订。
const cutoffZh = menu.delivery_context || '每天早上 6 点截单。';
const cutoffEn = menu.delivery_context_en || 'Orders close 6:00 AM daily.';

let reply = '';
let kind = 'new';

if (r.intent === 'catering') {
  kind = 'catering';
  reply = zh
    ? ['可以的！碗妈做的是餐盒式团体订餐 📦',
       '每人一份独立餐盒（不是 buffet，附一次性餐具）',
       '',
       '价格就是菜单原价，没有额外收费：',
       menuBlock,
       '',
       '告诉碗妈这 3 样，马上给你报价：',
       '① 哪天、几点要送到',
       '② 几位',
       '③ 送到哪里',
       '',
       '送达时间你指定几点就几点（±15 分钟内到）',
       'Pearl Suria 一带免运费 · 可开公司收据 ❤️'].join('\n')
    : ['Yes we do! BowlMama does bento-style group catering 📦',
       'One sealed box per person (not a buffet; disposable cutlery included).',
       '',
       'Price is simply the menu price — no hidden charges:',
       menuBlock,
       '',
       'Tell BowlMama these 3 things and you get a quote right away:',
       '1. Which day, and what time it must arrive',
       '2. How many people',
       '3. Delivery address',
       '',
       'We deliver at the exact time you name (within ±15 min).',
       'Free delivery around Pearl Suria · company receipt available ❤️'].join('\n');
} else if (cust.found === true && cust.reorder && cust.reorder.summary) {
  kind = 'returning';
  const name = (cust.profile && cust.profile.name) ? cust.profile.name : '';
  const reUrl = (zh ? cust.reorder.url : (cust.reorder.urlEn || cust.reorder.url)) + tag;
  reply = zh
    ? [(name ? name + '！' : '') + '👋 碗妈记得你 ❤️',
       '还是老样子吗？' + cust.reorder.summary,
       '',
       '点这里 30 秒付好 👇',
       reUrl,
       '',
       '想吃别的也行，' + label + '还有：',
       menuBlock].join('\n')
    : [(name ? 'Hi ' + name + '!' : 'Hi!') + ' 👋 BowlMama remembers you ❤️',
       'Same as last time? ' + cust.reorder.summary,
       '',
       'Tap here, 30 seconds to pay 👇',
       reUrl,
       '',
       'Or pick something else — ' + label + ' we have:',
       menuBlock].join('\n');
} else if (cust.found === true) {
  // 认得这个号码但上次点的菜现在都排不上 → 当熟客打招呼，但给通用链接
  kind = 'returning_nomatch';
  const name = (cust.profile && cust.profile.name) ? cust.profile.name : '';
  reply = zh
    ? [(name ? name + '！' : '') + '👋 碗妈记得你 ❤️',
       label + '可点：',
       menuBlock,
       '',
       '👇 点这里 30 秒下单',
       baseUrl,
       '',
       cutoffZh].join('\n')
    : [(name ? 'Hi ' + name + '!' : 'Hi!') + ' 👋 BowlMama remembers you ❤️',
       'Available ' + label + ':',
       menuBlock,
       '',
       '👇 Tap here, 30 seconds to order',
       baseUrl,
       '',
       cutoffEn].join('\n');
} else {
  kind = 'new';
  reply = zh
    ? ['碗妈的厨房欢迎你 🍲',
       label + '可点：',
       menuBlock,
       '',
       '🎁 新朋友第一单立减 RM5',
       '👇 30 秒下单，免注册',
       baseUrl,
       '',
       '送 Pearl Suria 一带 · ' + cutoffZh].join('\n')
    : ["Welcome to BowlMama's Kitchen 🍲",
       'Available ' + label + ':',
       menuBlock,
       '',
       '🎁 RM5 off your first order',
       '👇 30 seconds to order, no sign-up',
       baseUrl,
       '',
       'We deliver around Pearl Suria · ' + cutoffEn].join('\n');
}

return [{ json: { phone: r.phone, reply, kind, escalate: false, lang: r.lang, intent: r.intent } }];

// ============================
// 防抖 v3：**lead 文档自己就是水位线**，判定在服务端做完。
//
// v2 用 Google Sheet 做防抖（Append→Wait→Read→Gate→Mark 五个节点 + 一张表，
// 老板还要手工建 tab、定期清行）。v3 只用一次 HTTP：Lead Recheck 带着
// sinceTs + consume=1 去问「我是不是最新那条？是的话把攒下的消息给我」。
//
// 客户 3 秒内连发三条 → 三个执行都问这一句 → 前两条拿到 isLatest=false 静默退出，
// 只有最后一条继续，并且拿到**三条合并起来的文本**交给 AI。
// 「只回一条」和「看到全部内容」是两件事，v2 都做到了，v3 也必须都做到 ——
// 只做前者的话，客户说「我要订两份」「送 Pearl Suria」会变成只回答后半句。
//
// 任何一步读失败都**放行并退回自己这条**：宁可多回一条，绝不吃掉客户消息。
// ============================

const r = $('Router').first().json;
const fresh = $input.first().json || {};

// 服务端明确说了不是最新 → 让后面那条去回复
if (fresh.isLatest === false) return [];

// 服务端没给判定（端点挂了/字段缺失）→ 退化成「按自己这条处理」
const merged = typeof fresh.mergedText === 'string' ? fresh.mergedText.trim() : '';
const text = merged || r.text;

return [{ json: { phone: r.phone, text, lang: r.lang, intent: r.intent, merged: !!merged } }];

